/* From Uiverse.io by BurgiSimon  - Tags: simple, black, input, dark, modern, border, hover effect, css */
.__UIV_SCOPE__ .custom-input {
  max-width: 190px;
  background-color: #121212;
  border: 0px solid;
  box-shadow: 1px 1px 1px 1px rgb(131, 133, 129),
    -1px -1px 1px 1px rgb(100, 100, 100);
  border-radius: 4px;
  padding: 10px;
  color: whitesmoke;
  caret-color: white;
  outline: none;
  font-size: 16px;
  transition: background-color 0.3s ease;
}

.__UIV_SCOPE__ .custom-input:focus {
  background-color: #222;
  border: 1.5px solid rgb(189, 189, 189);
}

.__UIV_SCOPE__ .custom-input:hover {
  box-shadow: 1px 1px 1px 1px rgb(149, 151, 147),
    -1px -1px 1px 1px rgb(124, 124, 124);
}

.__UIV_SCOPE__ .custom-input:hover::placeholder {
  color: #999999;
}

.__UIV_SCOPE__ .custom-input::placeholder {
  color: #727272;
}
